    const SALES_WORKFLOW_NODE_OPTIONS = Array.from(new Map(SALES_WORKFLOW_PRESET.filter((row) => !row.comingSoon).map((row) => {
      const key = `${row.key}@@${row.label || row.note}`;
      return [key, { key: row.key, label: row.label || row.note, note: row.note || row.label }];
    })).values());
    const SALES_PERSONA_DEFAULT_KEYS = new Set([
      "local_bestseller",
      "hifly.video.create_by_tts",
      "ip_content_daily",
      "douyin_leads",
      "wecom_reply",
      "native_wechat_poll",
      "native_wechat_add_friend",
      "native_wechat_moments_engage",
    ]);

    function workflowNodeUsesPersonaDefaults(node) {
      if (!node) return false;
      const id = String(node.id || "");
      const key = String(node.ability_key || node.key || "");
      if (isNativeWechatWorkflowKey(key)) return false;
      if (key === "douyin_leads" && isSalesDouyinPrivateNode(node)) return false;
      if (key === "douyin_leads" && isSalesDouyinCollectionNode(node)) return false;
      if (key === "douyin_leads" && isSalesDouyinPreciseTouchNode(node)) return false;
      if (node.sales_preset || id.startsWith("sales_")) return true;
      return String(node.department_id || "") === "sales" && SALES_PERSONA_DEFAULT_KEYS.has(key);
    }

    function nativeWechatKeyFromSalesNote(note) {
      const text = String(note || "");
      if (text.includes("自动加好友")) return "native_wechat_add_friend";
      if (text.includes("自动拉群")) return "native_wechat_poll";
      if (text.includes("朋友圈点赞") || text.includes("朋友圈评论")) return "native_wechat_moments_engage";
      if (text.includes("私信接管")) return "native_wechat_poll";
      return "";
    }

    function isNativeWechatWorkflowKey(key) {
      return ["native_wechat_poll", "native_wechat_add_friend", "native_wechat_moments_engage"].includes(String(key || ""));
    }

    function nativeWechatWorkflowPlan(key, note, params = {}, options = {}) {
      const actionKey = String(key || "");
      const prompt = String(note || "").trim();
      const baseParams = {
        account_id: "pc-wechat-default",
        note: prompt,
        prompt,
        ...(params && typeof params === "object" ? params : {}),
      };
      const groupInvite = workflowBoolParam(baseParams.group_invite_enabled, false);
      if (Object.prototype.hasOwnProperty.call(baseParams, "group_invite_enabled")) baseParams.group_invite_enabled = groupInvite;
      if (groupInvite) {
        baseParams.group_invite_enabled = true;
        baseParams.group_invite_rule_status = baseParams.group_invite_rule_status || "pending_rules";
        baseParams.trigger = baseParams.trigger || "qualified_intent";
      }
      if (actionKey === "native_wechat_poll") {
        const title = groupInvite ? "个微自动拉群" : "个微私信接管";
        return {
          title,
          task_kind: "client_workflow",
          content: `H5 工作流：${title}`,
          payload: { action: "native_wechat_poll", params: baseParams },
        };
      }
      if (actionKey === "native_wechat_add_friend") {
        const targets = Array.isArray(baseParams.targets) ? baseParams.targets.filter(Boolean) : [];
        if (options.requireTargets && !targets.length) throw new Error("请填写手机号或微信号");
        return {
          title: "个微自动加好友",
          task_kind: "client_workflow",
          content: "H5 工作流：个微自动加好友",
          payload: { action: "native_wechat_add_friend", params: { ...baseParams, targets } },
        };
      }
      if (actionKey === "native_wechat_moments_engage") {
        const rawTargets = Array.isArray(baseParams.contact_wx_nos) ? baseParams.contact_wx_nos : baseParams.targets;
        const targets = Array.from(new Set((Array.isArray(rawTargets) ? rawTargets : []).map((value) => String(value || "").trim()).filter(Boolean)));
        if (options.requireTargets && !targets.length) throw new Error("请选择或填写朋友圈联系人");
        const momentParams = { ...baseParams };
        [
          "group_invite_enabled",
          "group_invite_memory_doc_id",
          "group_invite_keywords",
          "group_invite_contacts",
          "group_invite_primary_contact",
          "group_invite_primary_contact_name",
          "group_invite_welcome_message",
          "group_invite_rule_status",
          "group_invite_targets_source",
          "group_invite_members",
          "group_invite_manager_contacts",
          "followup_action",
          "group_invite_rules",
          "trigger",
        ].forEach((key) => delete momentParams[key]);
        return {
          title: "朋友圈点赞评论",
          task_kind: "client_workflow",
          content: "H5 工作流：朋友圈点赞评论",
          payload: {
            action: "native_wechat_moments_engage",
            params: { ...momentParams, contact_wx_nos: targets, targets, moment_action: baseParams.moment_action || "like_comment", max_scrolls: baseParams.max_scrolls || 6 },
          },
        };
      }
      throw new Error("这个个微节点暂不支持加入工作流");
    }

    function salesWorkflowPlaceholderPlan(row) {
      const label = row && (row.label || row.note || "敬请期待") || "敬请期待";
      return {
        title: label,
        task_kind: "workflow_placeholder",
        content: `H5 工作流占位：${label}`,
        payload: {
          action: "workflow_coming_soon",
          skip_execution: true,
          note: row && row.note || label,
          platform: String(row && row.key || "").startsWith("wechat_channels") ? "wechat_channels" : "",
        },
      };
    }

    function workflowNodeIsPlaceholder(node) {
      if (!node || typeof node !== "object") return false;
      const plan = node.plan && typeof node.plan === "object" ? node.plan : {};
      const payload = plan.payload && typeof plan.payload === "object" ? plan.payload : {};
      const markerText = [node.ability_label, node.label, node.note, plan.title, payload.note]
        .map((value) => String(value || ""))
        .join(" ");
      return !!(
        node.comingSoon
        || node.coming_soon
        || node.workflow_placeholder
        || node.placeholder
        || payload.skip_execution
        || payload.action === "workflow_coming_soon"
        || markerText.includes("敬请期待")
      );
    }

    function normalizeSalesWorkflowNode(node) {
      if (!node || typeof node !== "object") return node;
      if (workflowNodeIsPlaceholder(node)) {
        return {
          ...node,
          comingSoon: true,
          workflow_placeholder: true,
          plan: node.plan && typeof node.plan === "object" ? node.plan : salesWorkflowPlaceholderPlan(node),
          children: [],
        };
      }
      const plan = node.plan && typeof node.plan === "object" ? node.plan : {};
      const payload = plan.payload && typeof plan.payload === "object" ? plan.payload : {};
      const action = String(payload.action || (payload.params || {}).action || "");
      const isSalesNode = !!node.sales_preset || String(node.id || "").startsWith("sales_") || String(node.department_id || "") === "sales";
      if (!isSalesNode || action !== "wecom_poll_reply") {
        return { ...node, children: workflowChildActions(node).map(normalizeSalesWorkflowNode).filter(Boolean) };
      }
      const note = String(node.note || node.ability_label || plan.title || "");
      const nativeKey = nativeWechatKeyFromSalesNote(note);
      if (!nativeKey) return node;
      const lookup = abilityLookup(nativeKey);
      return {
        ...node,
        ability_key: nativeKey,
        department_id: lookup && lookup.department ? lookup.department.id || "private_domain" : "private_domain",
        department_name: lookup && lookup.department ? lookup.department.name || "私域销冠" : "私域销冠",
        plan: nativeWechatWorkflowPlan(nativeKey, note),
        children: workflowChildActions(node).map(normalizeSalesWorkflowNode).filter(Boolean),
      };
    }

    function normalizeSalesWorkflowNodes(nodes) {
      const normalized = (Array.isArray(nodes) ? nodes : []).map(normalizeSalesWorkflowNode).filter(Boolean);
      const cleaned = normalized.map((node) => {
        if (!node || typeof node !== "object") return node;
        const children = workflowChildActions(node);
        if (!children.length) return node;
        const isSales = !!node.sales_preset || String(node.id || "").startsWith("sales_") || String(node.department_id || "") === "sales";
        if (!isSales) return node;
        const plan = node.plan && typeof node.plan === "object" ? { ...node.plan } : {};
        const payload = plan.payload && typeof plan.payload === "object" ? { ...plan.payload } : {};
        const params = payload.params && typeof payload.params === "object" ? { ...payload.params } : {};
        const remaining = [];
        children.forEach((child) => {
          const childPlan = child && child.plan && typeof child.plan === "object" ? child.plan : {};
          const childPayload = childPlan.payload && typeof childPlan.payload === "object" ? childPlan.payload : {};
          const childParams = childPayload.params && typeof childPayload.params === "object" ? childPayload.params : {};
          const childType = String(child && (child.action_type || child.type) || "").trim().toLowerCase();
          const childAction = String(childPayload.action || child && child.ability_key || "").trim().toLowerCase();
          const label = `${child && child.ability_label || ""} ${child && child.note || ""}`;
          const legacyGroupType = ["native", "wechat", "group_invite"].join("_");
          if (childType === legacyGroupType || (childAction === "native_wechat_poll" && label.includes("自动拉群"))) {
            Object.assign(params, childParams);
            params.group_invite_enabled = true;
            params.followup_action = "group_invite";
            params.group_invite_rule_status = params.group_invite_rule_status || "pending_rules";
            params.trigger = params.trigger || "qualified_intent";
            return;
          }
          if (childType === "native_wechat_add_friend" || childAction === "native_wechat_add_friend") {
            if (String(payload.action || "") === "stranger_message" || String(node.ability_key || "") === "douyin_leads") {
              params.wechat_add_friend_enabled = true;
              params.wechat_add_friend_targets_source = "douyin_private_message_phone";
              payload.action = "stranger_message";
              return;
            }
          }
          remaining.push(child);
        });
        payload.params = params;
        plan.payload = payload;
        return { ...node, plan, ...(remaining.length ? { children: remaining } : {}) };
      });
      normalized.splice(0, normalized.length, ...cleaned);
      return migrateSalesDouyinAddFriendChildren(foldSalesDouyinFollowupNodes(normalized));
    }

    function salesWorkflowActionForNote(note) {
      const text = String(note || "");
      if (text.includes("我的评论区")) return "self_comment_monitor";
      if (text.includes("精准用户触达") || text.includes("精准触达")) return "precise_touch";
      if (text.includes("养号")) return "account_nurture";
      if (text.includes("发布后采集") || text.includes("关键词抓取")) return "search_collect";
      if (text.includes("回复") && text.includes("评论")) return "reply_comments";
      if (text.includes("@精准") || text.includes("评论并@") || text.includes("自己评论区接管")) return "mention_comment";
      if (text.includes("关注") && text.includes("评论")) return "follow_comment";
      if (text.includes("主动私信") || text.includes("私信10")) return "direct_message";
      if (text.includes("私信接管") || text.includes("私信引流")) return "stranger_message";
      return "search_collect";
    }

    const SALES_DOUYIN_FOLLOWUP_ACTIONS = ["follow_comment", "mention_comment", "direct_message"];

    function normalizeSalesDouyinFollowupActions(value) {
      const selected = new Set((Array.isArray(value) ? value : []).map((item) => String(item || "").trim().toLowerCase()));
      return SALES_DOUYIN_FOLLOWUP_ACTIONS.filter((action) => selected.has(action));
    }

    function salesDouyinNodeAction(node) {
      const plan = node && node.plan && typeof node.plan === "object" ? node.plan : {};
      const payload = plan.payload && typeof plan.payload === "object" ? plan.payload : {};
      const params = payload.params && typeof payload.params === "object" ? payload.params : {};
      const inferred = salesWorkflowActionForNote(node && (node.note || node.ability_label) || plan.title || "");
      const explicit = String(payload.action || params.sales_action || "").trim().toLowerCase();
      if (["search_collect", "precise_touch", "self_comment_monitor", "account_nurture", "reply_comments", "follow_comment", "mention_comment", "direct_message", "stranger_message"].includes(explicit)) {
        return explicit === "search_collect" && inferred !== "search_collect" ? inferred : explicit;
      }
      return inferred;
    }

    function isSalesDouyinCollectionNode(node) {
      return String(node && (node.ability_key || node.key) || "") === "douyin_leads"
        && salesDouyinNodeAction(node) === "search_collect";
    }

    function isSalesDouyinPreciseTouchNode(node) {
      return String(node && (node.ability_key || node.key) || "") === "douyin_leads"
        && salesDouyinNodeAction(node) === "precise_touch";
    }

    function foldSalesDouyinFollowupNodes(nodes) {
      const prepared = [];
      let currentCollection = null;
      (Array.isArray(nodes) ? nodes : []).forEach((node) => {
        const action = salesDouyinNodeAction(node);
        const isSalesDouyin = String(node && (node.ability_key || node.key) || "") === "douyin_leads"
          && (node.sales_preset || String(node.id || "").startsWith("sales_") || String(node.department_id || "") === "sales");
        if (isSalesDouyin && action === "search_collect") {
          currentCollection = node;
          const collectionPlan = currentCollection.plan && typeof currentCollection.plan === "object" ? { ...currentCollection.plan } : {};
          const collectionPayload = collectionPlan.payload && typeof collectionPlan.payload === "object" ? { ...collectionPlan.payload } : {};
          const collectionParams = collectionPayload.params && typeof collectionPayload.params === "object" ? { ...collectionPayload.params } : {};
          const legacyCollectionActions = [
            ...(Array.isArray(collectionParams.followup_actions) ? collectionParams.followup_actions : []),
            ...(Array.isArray(collectionParams.touch_actions) ? collectionParams.touch_actions : []),
          ];
          collectionParams.followup_actions = [];
          delete collectionParams.touch_actions;
          collectionParams.customer_scope = "current_collection_batch";
          collectionParams.reply_precise_comments = workflowBoolParam(collectionParams.reply_precise_comments, legacyCollectionActions.includes("reply_comments"));
          collectionParams.reply_comment_mode = ["fixed", "ai", "rewrite"].includes(String(collectionParams.reply_comment_mode || collectionParams.comment_mode || "fixed").toLowerCase())
            ? String(collectionParams.reply_comment_mode || collectionParams.comment_mode || "fixed").toLowerCase()
            : "fixed";
          collectionParams.reply_comment_text = String(collectionParams.reply_comment_text || collectionParams.comment_text || "");
          collectionParams.reply_comment_prompt = String(collectionParams.reply_comment_prompt || collectionParams.comment_prompt || "");
          collectionParams.reply_comment_seed_text = String(collectionParams.reply_comment_seed_text || collectionParams.comment_seed_text || "");
          collectionPayload.params = collectionParams;
          collectionPlan.payload = collectionPayload;
          currentCollection.plan = collectionPlan;
          prepared.push(node);
          return;
        }
        if (isSalesDouyin && (SALES_DOUYIN_FOLLOWUP_ACTIONS.includes(action) || action === "reply_comments")) {
          if (action === "reply_comments" && currentCollection) {
            const collectionPlan = currentCollection.plan && typeof currentCollection.plan === "object" ? { ...currentCollection.plan } : {};
            const collectionPayload = collectionPlan.payload && typeof collectionPlan.payload === "object" ? { ...collectionPlan.payload } : {};
            const collectionParams = collectionPayload.params && typeof collectionPayload.params === "object" ? { ...collectionPayload.params } : {};
            collectionParams.reply_precise_comments = true;
            collectionPayload.params = collectionParams;
            collectionPlan.payload = collectionPayload;
            currentCollection.plan = collectionPlan;
          }
          // Legacy standalone follow-up nodes must not make collection execute
          // touch actions. The standalone precise-touch node owns that work.
          return;
        }
        prepared.push(node);
      });
      return prepared;
    }
