    async function refillRunToWorkbench(runId) {
      let run = (state.runs || []).find((row) => String(row.id || "") === String(runId)) || null;
      if (!run || !run.payload) {
        const data = await api(`/api/scheduled-tasks/runs/${encodeURIComponent(runId)}`);
        run = data.run || null;
        if (run) mergeRuns([run]);
      }
      if (!run) {
        toast("没有找到这条执行记录");
        return;
      }
      const abilityKey = abilityKeyFromRun(run);
      if (!abilityKey || !abilityLookup(abilityKey)) {
        toast("这条记录暂时无法定位到对应工作台");
        return;
      }
      openAbilityView(abilityKey);
      setTimeout(() => {
        refillAbilityFieldsFromRun(run);
        toast("已带入上次任务参数，可修改后重新下发");
      }, 120);
    }

    function setMomentStatus(recordId, text, isError = false) {
      const el = document.querySelector(`[data-moment-status="${cssEscape(String(recordId || ""))}"]`);
      if (!el) return;
      el.textContent = text || "";
      el.style.color = isError ? "var(--red)" : "var(--muted)";
    }

    function selectedMomentRecords() {
      return Array.from(document.querySelectorAll("[data-moment-select]:checked")).map((input) => {
        const recordId = String(input.dataset.momentSelect || "").trim();
        const item = input.closest("[data-moment-record]");
        const body = item ? (item.querySelector(".task-detail-moments-copy")?.textContent || "").trim() : "";
        const promptInputs = item ? Array.from(item.querySelectorAll(`[data-moment-prompt="${cssEscape(recordId)}"]:checked`)) : [];
        const prompts = promptInputs.map((el) => {
          const label = el.closest("label");
          const raw = label ? label.textContent || "" : "";
          return raw.replace(/^配图\s*\d+\s*[:：]\s*/, "").trim();
        }).filter(Boolean).slice(0, 3);
        const title = item ? (item.querySelector(".moment-summary span")?.textContent || "").replace(/^\d+\.\s*/, "").trim() : "";
        const memoryDocIds = item ? String(item.dataset.momentMemoryDocIds || "").split(",").map((id) => id.trim()).filter(Boolean) : [];
        let referenceImageUrls = [];
        try {
          referenceImageUrls = item ? referenceImageUrlsFromValue(JSON.parse(item.dataset.momentReferenceImageUrls || "[]"), 8) : [];
        } catch (_) {
          referenceImageUrls = [];
        }
        return { recordId, body, prompts, title, memory_doc_ids: memoryDocIds, reference_image_urls: referenceImageUrls };
      }).filter((row) => row.recordId);
    }

    function selectedDraftCopies(task) {
      const selector = `[data-draft-copy-select]:checked${task ? `[data-draft-task="${cssEscape(task)}"]` : ""}`;
      return Array.from(document.querySelectorAll(selector)).map((input) => {
        const item = input.closest(".copy-item, .moment-item");
        if (!item) return "";
        const title = (item.querySelector(".copy-summary span, .moment-summary span")?.textContent || "").replace(/^\d+\.\s*/, "").trim();
        const body = (item.querySelector(".task-detail-moments-copy")?.textContent || "").trim();
        return [title, body].filter(Boolean).join("\n");
      }).filter(Boolean);
    }

    async function copySelectedDrafts(task) {
      const rows = selectedDraftCopies(task);
      if (!rows.length) {
        toast("请先勾选要复制的文案");
        return;
      }
      const ok = await copyText(rows.join("\n\n---\n\n"));
      toast(ok ? `已复制 ${rows.length} 条文案` : "复制失败，请长按文案手动复制");
    }

    function toggleDraftGroupSelection(task) {
      const selector = `[data-draft-copy-select]${task ? `[data-draft-task="${cssEscape(task)}"]` : ""}`;
      const inputs = Array.from(document.querySelectorAll(selector));
      if (!inputs.length) return;
      const shouldCheck = inputs.some((input) => !input.checked);
      inputs.forEach((input) => { input.checked = shouldCheck; });
    }

    async function generateSelectedMomentImages(btn) {
      if (activeMomentImageRun(state.currentRunDetailId)) {
        toast("当前图片生成任务还在执行中，请完成后再生成");
        return;
      }
      const selected = selectedMomentRecords();
      if (!selected.length) {
        toast("请先选择要出图的朋友圈文案");
        return;
      }
      if (selected.length > 5) {
        toast("一次最多选择 5 条朋友圈文案");
        return;
      }
      const oldText = btn ? btn.textContent : "";
      if (btn) {
        btn.disabled = true;
        btn.textContent = "下发中...";
      }
      const batchId = `h5_moment_img_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
      const batchCreatedAt = new Date().toISOString();
      try {
        const records = selected.map((record) => {
          const prompts = (record.prompts && record.prompts.length ? record.prompts : [record.body || record.title || "朋友圈配图"]).slice(0, 3);
          setMomentStatus(record.recordId, "已下发到 online，等待客户端生成...");
          return { ...record, prompts, memory_doc_ids: record.memory_doc_ids || [] };
        });
        const created = await submitOnceClientTask({
            title: "朋友圈图片生成",
            taskKind: "client_workflow",
            content: `生成 ${records.length} 条朋友圈配图`,
            payload: {
              action: "ip_moments_generate_images",
              params: {
                source: "h5_scheduled_run_detail",
                source_run_id: state.currentRunDetailId || "",
                batch_id: batchId,
                batch_created_at: batchCreatedAt,
                records,
              },
            },
        });
        const run = created && Array.isArray(created.runs) && created.runs[0] && typeof created.runs[0] === "object" ? created.runs[0] : null;
        if (run && run.id && !(state.runs || []).some((row) => String(row.id || "") === String(run.id))) {
          state.runs = [run].concat(state.runs || []);
        }
        showTaskSuccessDialog("朋友圈图片生成任务已下发，可在工作历史查看进度。");
        if (state.currentRunDetailId) {
          setTimeout(() => openRunDetail(state.currentRunDetailId, state.runDetailBackTab || "runList"), 1200);
        }
      } catch (err) {
        toast(err.message || "朋友圈出图任务下发失败");
        selected.forEach((record) => setMomentStatus(record.recordId, err.message || "任务下发失败", true));
      } finally {
        if (btn) {
          const stillBusy = activeMomentImageRun(state.currentRunDetailId);
          btn.disabled = !!stillBusy;
          btn.textContent = stillBusy ? "图片生成中" : (oldText || "生成选中图片");
        }
      }
    }

    async function runTaskNow(taskId, btn) {
      if (!taskId) return;
      const oldText = btn ? btn.textContent : "";
      const task = (state.tasks || []).find((row) => String(row.id || "") === String(taskId)) || null;
      const taskKind = String(task && task.task_kind || "").trim();
      const optimisticRunId = addOptimisticRun(
        { task_kind: taskKind, payload: task && task.payload ? task.payload : {} },
        task ? task.title : "",
        isServerSideScheduledKind(taskKind)
      );
      if (btn) {
        btn.disabled = true;
        btn.textContent = "下发中...";
      }
      try {
        const data = await api(`/api/scheduled-tasks/tasks/${encodeURIComponent(taskId)}/run-now`, {
          method: "POST",
          blocking: "正在下发任务",
          json: {},
        });
        removeRun(optimisticRunId);
        mergeRuns(data.runs || []);
        renderOfficeEmployees();
        renderWorkList();
        showTaskSuccessDialog("任务已下发执行，可在工作历史查看进度。");
        await Promise.all([loadTasks({ reset: true }), loadRuns({ reset: true })]);
      } catch (err) {
        removeRun(optimisticRunId);
        renderOfficeEmployees();
        renderWorkList();
        toast(err.message || "下发失败");
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.textContent = oldText || "立即执行";
        }
      }
    }

    function invalidateSelectedDeviceData() {
      state.deviceContextRequestSeq += 1;
      state.taskListRequestSeq += 1;
      state.runListRequestSeq += 1;
      state.mountedAccountsRequestSeq += 1;
      state.publishAccountsRequestSeq += 1;
      state.workflowActiveRequestSeq += 1;
      state.douyinStatusRequestSeq += 1;
      state.recorderRecordsRequestSeq += 1;
      state.recorderKnownRequestSeq += 1;
      state.tasks = [];
      state.runs = [];
      state.taskListOffset = 0;
      state.taskListHasNext = false;
      state.runListOffset = 0;
      state.runListHasNext = false;
      state.runListTotal = 0;
      state.runListLoading = false;
      state.workflowRunDateLoaded = {};
      state.workflowRunDateLoading = {};
      state.workflowActive = null;
      state.mountedAccounts = [];
      state.mountedAccountDefaults = {};
      state.mountedAccountsLoaded = false;
      state.mountedAccountsLoading = false;
      state.publishAccounts = [];
      state.publishAccountsLoaded = false;
      state.publishAccountsLoading = false;
      state.douyinStatus = null;
      state.recorderRecords = [];
      state.recorderKnownNames = [];
      state.recorderSyncedFiles = [];
      state.recorderPage = 1;
      state.recorderTotal = 0;
      state.officeSummaryLoadedAt = 0;
      state.officeSummaryLoading = null;
    }

    function ensureSelectedInstallationId() {
      const selected = String(state.selectedInstallationId || "").trim();
      if (!state.devicesLoaded && !(state.devices || []).length) return selected;
      if (selected && state.devices.some((d) => String(d.installation_id || "") === selected)) return selected;
      const previous = state.selectedInstallationId;
      const preferred = state.devices.find((d) => d.online && d.installation_id) || state.devices.find((d) => d.installation_id);
      const next = String((preferred || {}).installation_id || "");
      state.selectedInstallationId = next;
      if (next) localStorage.setItem(brandStorageKey("lobster_h5_selected_installation_id"), next);
      else localStorage.removeItem(brandStorageKey("lobster_h5_selected_installation_id"));
      if (previous !== next) invalidateSelectedDeviceData();
      return next;
    }

    async function refreshSelectedDeviceData(requestId = state.deviceContextRequestSeq) {
      const installationId = currentInstallationId();
      if (!installationId || requestId !== state.deviceContextRequestSeq) return;
      const requests = [
        loadMountedAccounts(true),
        loadTasks({ reset: true, limit: 80 }),
        loadRuns({ reset: true, limit: 20, compact: true }),
        loadWorkflowActive(),
        loadWorkflowTemplates(true),
      ];
      if (activeViewKey() === "douyinLeads") requests.push(loadDouyinStatus());
      if (activeViewKey() === "recorder") {
        requests.push(loadRecorderRecords());
        requests.push(loadRecorderKnownNames());
      }
      await Promise.allSettled(requests);
      if (requestId !== state.deviceContextRequestSeq || installationId !== currentInstallationId()) return;
      await loadPublishAccounts(true).catch(() => {});
      renderMountedAccounts();
      renderOfficeEmployees();
      renderWorkList();
    }

    function setSelectedInstallationId(value) {
      const next = String(value || "").trim();
      const hit = next ? (state.devices || []).find((d) => String(d.installation_id || "") === next) : null;
      const previous = String(state.selectedInstallationId || "").trim();
      state.selectedInstallationId = hit ? next : "";
      if (state.selectedInstallationId) localStorage.setItem(brandStorageKey("lobster_h5_selected_installation_id"), state.selectedInstallationId);
      else localStorage.removeItem(brandStorageKey("lobster_h5_selected_installation_id"));
      renderProfileDeviceSelect();
      if (previous === state.selectedInstallationId) return;
      invalidateSelectedDeviceData();
      renderProfileDeviceSelect();
      fillPublishPlatformSelect();
      fillPublishRunPlatformSelect();
      syncRecorderNativeAuth();
      const requestId = state.deviceContextRequestSeq;
      refreshSelectedDeviceData(requestId).catch((err) => toast(err.message || "设备数据刷新失败"));
    }

    function selectedDevice() {
      const id = ensureSelectedInstallationId();
      return (state.devices || []).find((d) => String(d.installation_id || "") === id) || null;
    }

    function currentInstallationId() {
      return ensureSelectedInstallationId();
    }

    function liveExecutorState() {
      if (!state.liveExecutor || typeof state.liveExecutor !== "object") {
        state.liveExecutor = {
          image: null,
          imagePreviewUrl: "",
          imageUploadPromise: null,
          imageUploading: false,
          configAction: "",
          tasks: [],
          queue: Promise.resolve(),
          poller: null,
          recorder: { stream: null, recorder: null, chunks: [], startedAt: 0, timer: null, taskId: "" },
        };
      }
      if (!state.liveExecutor.recorder) {
        state.liveExecutor.recorder = { stream: null, recorder: null, chunks: [], startedAt: 0, timer: null, taskId: "" };
      }
      return state.liveExecutor;
    }

    function liveExecutorPromptText() {
      return String(($("liveExecutorPrompt") && $("liveExecutorPrompt").value) || "").trim();
    }

    function liveExecutorSelectedInstallationId() {
      const selectValue = String(($("liveExecutorDeviceSelect") && $("liveExecutorDeviceSelect").value) || "").trim();
      if (selectValue) return selectValue;
      return currentInstallationId();
    }

    function liveExecutorDeviceLabel(device) {
      if (!device) return "未选择设备";
      return deviceSelectorLabel(device);
    }

    function liveExecutorOnlineRows() {
      return (state.devices || []).filter((device) => device && device.online && device.installation_id);
    }

    async function ensureLiveExecutorOnlineInstallationId(options = {}) {
      const refresh = !!(options && options.refresh);
      const preferred = String((options && options.preferred) || liveExecutorSelectedInstallationId() || "").trim();
      if (refresh || !liveExecutorOnlineRows().length || (preferred && !liveExecutorOnlineRows().some((device) => String(device.installation_id || "") === preferred))) {
        await refreshDeviceStatus().catch(() => {});
      }
      const rows = liveExecutorOnlineRows();
      const current = String((options && options.preferred) || liveExecutorSelectedInstallationId() || "").trim();
      const hit = current ? rows.find((device) => String(device.installation_id || "") === current) : null;
      const next = hit || rows[0] || null;
      if (!next) {
        state.selectedInstallationId = "";
        localStorage.removeItem(brandStorageKey("lobster_h5_selected_installation_id"));
        renderLiveExecutorDeviceSelect();
        throw new Error("当前没有在线 Online 设备，请先启动或刷新 Online 客户端");
      }
      const iid = String(next.installation_id || "").trim();
      if (iid && iid !== String(state.selectedInstallationId || "").trim()) {
        state.selectedInstallationId = iid;
        localStorage.setItem(brandStorageKey("lobster_h5_selected_installation_id"), iid);
      }
      const select = $("liveExecutorDeviceSelect");
      if (select) select.value = iid;
      renderLiveExecutorDeviceSelect();
      return iid;
    }

    function renderLiveExecutorDeviceSelect() {
      const select = $("liveExecutorDeviceSelect");
      const hint = $("liveExecutorDeviceHint");
      if (!select) return;
      const rows = liveExecutorOnlineRows();
      select.innerHTML = rows.length
        ? rows.map((device) => optionHtml(device.installation_id || "", liveExecutorDeviceLabel(device))).join("")
        : '<option value="">暂无在线设备</option>';
      const current = String(state.selectedInstallationId || "").trim();
      if (current && rows.some((device) => String(device.installation_id || "") === current)) {
        select.value = current;
      } else if (rows[0]) {
        setSelectedInstallationId(rows[0].installation_id || "");
        select.value = rows[0].installation_id || "";
      }
      if (hint) {
        hint.textContent = rows.length
          ? `在线 ${rows.length} 台，任务会下发到当前选择设备`
          : "请先启动并登录 Online 客户端";
      }
      renderLiveExecutorConfigModal();
    }

