    document.addEventListener("click", (evt) => {
      const removeBtn = evt.target.closest("[data-asset-picker-remove]");
      if (removeBtn) {
        evt.preventDefault();
        evt.stopPropagation();
        const id = removeBtn.dataset.assetPickerRemove || "";
        const index = Number(removeBtn.dataset.assetPickerRemoveIndex || -1);
        const rows = assetPickerSelectionRows(id);
        if (index >= 0 && rows[index]) {
          rows.splice(index, 1);
          setAssetPickerSelectionRows(id, rows, false);
        }
        return;
      }
      const pickerBtn = evt.target.closest("[data-asset-picker-open]");
      if (pickerBtn) {
        evt.preventDefault();
        openAssetPickerModal(pickerBtn.dataset.assetPickerOpen || "");
        return;
      }
      const btn = evt.target.closest("[data-asset-upload-trigger]");
      if (!btn) return;
      // Labels activate the file input natively, which is more reliable than
      // a programmatic click in Android WebView file choosers.
      if (btn.tagName === "LABEL") return;
      evt.preventDefault();
      const id = btn.dataset.assetUploadTrigger || "";
      const input = id ? $(`${id}File`) : null;
      if (input) input.click();
    });
    document.addEventListener("error", (evt) => {
      const image = evt.target;
      if (!(image instanceof HTMLImageElement)) return;
      if (image.matches("[data-content-document-cover], [data-content-record-card-image], [data-asset-picker-library-image]")) {
        image.classList.add("hidden");
        if (image.matches("[data-content-record-card-image]")) {
          image.remove();
          return;
        }
        const fallback = image.nextElementSibling;
        if (fallback) fallback.classList.remove("hidden");
      }
    }, true);

    window.__lobsterHandleBack = function () {
      if (closeMobileMediaPreview()) return true;
      const visibleDialogs = Array.from(document.querySelectorAll('[role="dialog"]:not(.hidden)'));
      const dialog = visibleDialogs[visibleDialogs.length - 1];
      if (dialog) {
        const close = dialog.querySelector('button[aria-label*="关闭"], button[id*="Close"], button[id*="Cancel"]');
        if (close) {
          close.click();
          return true;
        }
      }
      if (activeViewKey() !== "office") {
        $("topBackBtn")?.click();
        return true;
      }
      return false;
    };
