    $("voiceMicBtn")?.addEventListener("touchstart", startVoiceCapture, { passive: false });
    document.addEventListener("mousedown", (evt) => {
      const btn = evt.target.closest(".office-voice-entry");
      if (!btn) return;
      startOfficeVoiceCapture(evt).catch((err) => {
        state.officeVoiceHoldActive = false;
        setOfficeVoiceButtonPressed(false);
        toast(err.message || "无法启动语音识别");
      });
    });
    document.addEventListener("touchstart", (evt) => {
      const btn = evt.target.closest(".office-voice-entry");
      if (!btn) return;
      startOfficeVoiceCapture(evt).catch((err) => {
        state.officeVoiceHoldActive = false;
        setOfficeVoiceButtonPressed(false);
        toast(err.message || "无法启动语音识别");
      });
    }, { passive: false });
    window.addEventListener("mouseup", (evt) => {
      if (state.voiceCaptureTarget === "voice") stopVoiceCapture(evt);
    });
    window.addEventListener("touchend", (evt) => {
      if (state.voiceCaptureTarget === "voice") stopVoiceCapture(evt);
    });
    window.addEventListener("touchcancel", (evt) => {
      if (state.voiceCaptureTarget === "voice") stopVoiceCapture(evt);
    });
    window.addEventListener("mouseup", stopOfficeVoiceCapture);
    window.addEventListener("touchend", stopOfficeVoiceCapture);
    window.addEventListener("touchcancel", stopOfficeVoiceCapture);
    $("voiceMicBtn")?.addEventListener("mouseleave", stopVoiceCapture);
    document.addEventListener("mouseleave", stopOfficeVoiceCapture);
    $("voiceToMessagesBtn")?.addEventListener("click", () => sendVoiceDraftToMessages(false));
    $("voiceClearBtn")?.addEventListener("click", clearVoiceDraft);
    $("voiceExpandBtn")?.addEventListener("click", () => {
      state.voiceExpanded = !state.voiceExpanded;
      syncVoiceDraftDisplay();
    });
    $("voiceActionCards")?.addEventListener("click", (evt) => {
      const planAction = evt.target.closest("[data-voice-plan-action]");
      if (planAction) {
        const mode = String(planAction.dataset.voicePlanAction || "").trim();
        const plan = buildVoiceExecutionPlan();
        if (!plan) {
          toast("请先录入一段语音内容");
          return;
        }
        if (mode === "execute") {
          executeVoicePlan().catch((err) => toast(err.message || "执行失败，请稍后重试"));
          return;
        }
        routeVoicePlanToRefine(plan);
        return;
      }
      const actionCard = evt.target.closest("[data-voice-action-index]");
      if (actionCard) {
        const index = Number(actionCard.dataset.voiceActionIndex || "-1");
        const action = Number.isFinite(index) ? (state.voiceActions[index] || null) : null;
        if (!action) return;
        const kind = String(action.kind || "");
        const payload = action.payload && typeof action.payload === "object" ? action.payload : {};
        const content = String(payload.content || state.voiceDraft || "").trim();
        const plan = buildVoiceExecutionPlan();
        if (!content) {
          toast("请先录入一段语音内容");
          return;
        }
        if (shouldRouteVoiceActionThroughPlan(kind, plan)) {
          if (plan.direct) {
            executeVoicePlan().catch((err) => toast(err.message || "鎵ц澶辫触锛岃绋嶅悗閲嶈瘯"));
          } else {
            routeVoicePlanToRefine(plan);
          }
          return;
        }
        if (kind === "submit_message") {
          sendVoiceDraftToMessages(true, "", content);
          return;
        }
        switchTab("messages");
        setMessageTemplate(content);
        return;
      }
      const card = evt.target.closest("[data-voice-template], [data-voice-submit]");
      if (!card) return;
      if (card.dataset.voiceSubmit === "1") {
        sendVoiceDraftToMessages(true);
        return;
      }
      sendVoiceDraftToMessages(false, card.dataset.voiceTemplate || "");
    });

    $("composerFileInput")?.addEventListener("change", async () => {
      const files = Array.from($("composerFileInput").files || []);
      $("composerFileInput").value = "";
      if (!files.length) return;
      if (!state.token) {
        toast("请先登录后再添加素材");
        return;
      }
      uploadComposerFiles(files.slice(0, Math.max(0, 8 - state.uploads.length))).catch((err) => {
        toast(err.message || "素材上传失败");
      });
    });

    $("loginForm").addEventListener("submit", async (evt) => {
      evt.preventDefault();
      $("loginBtn").disabled = true;
      try {
        const phone = normalizePhone($("phone").value);
        const code = $("smsCode").value.trim();
        if (!phone) throw new Error("请输入有效手机号");
        if (!code) throw new Error("请输入短信验证码");
        const resp = await blockingFetch(apiUrl("/auth/register-phone"), {
          method: "POST",
          headers: authHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ phone, code, brand_mark: H5_BRAND_MARK }),
        }, "正在登录");
        const data = await resp.json().catch(() => ({}));
        if (!resp.ok) throw new Error(data.detail || "进入失败");
        state.token = data.access_token;
        localStorage.setItem(H5_TOKEN_KEY, state.token);
        state.user = null;
        localStorage.removeItem(H5_USER_CACHE_KEY);
        await loadMe();
      } catch (err) {
        toast(err.message || "进入失败");
        await refreshCaptcha();
      } finally {
        $("loginBtn").disabled = false;
      }
    });

    $("passwordLoginForm").addEventListener("submit", async (evt) => {
      evt.preventDefault();
      $("passwordLoginBtn").disabled = true;
      try {
        const account = ($("passwordAccount").value || "").trim();
        const password = $("loginPassword").value;
        if (!account) throw new Error("请输入账号或手机号");
        if (!password) throw new Error("请输入密码");
        const resp = await blockingFetch(apiUrl("/auth/login-phone-password"), {
          method: "POST",
          headers: authHeaders({ "Content-Type": "application/json" }),
          body: JSON.stringify({ account, password, brand_mark: H5_BRAND_MARK }),
        }, "正在登录");
        const data = await resp.json().catch(() => ({}));
        if (!resp.ok) throw new Error(normalizeAuthErrorDetail(data.detail) || "登录失败");
        state.token = data.access_token;
        localStorage.setItem(H5_TOKEN_KEY, state.token);
        state.user = null;
        localStorage.removeItem(H5_USER_CACHE_KEY);
        await loadMe();
      } catch (err) {
        toast(err.message || "登录失败");
      } finally {
        $("passwordLoginBtn").disabled = false;
      }
    });

    async function submitChatMessage(rawContent = null, options = {}) {
      const input = $("messageInput");
      const fromComposer = rawContent === null;
      const content = String(fromComposer ? input.value : rawContent || "").trim();
      const attachments = readyAttachments();
      if (hasUploadingImages()) {
        toast("素材还在上传中，请稍等");
        return false;
      }
      if (!content && !attachments.length) return false;
      if ($("sendBtn").disabled) {
        toast("上一条指令正在提交，请稍等");
        return false;
      }
      if (fromComposer) {
        input.value = "";
        autosizeMessageInput();
      }
      const queueMode = options.queueMode === "steer" ? "steer" : "normal";
      const targetMessageId = queueMode === "steer" ? String(options.targetMessageId || "").trim() : "";
      if (queueMode === "steer" && !targetMessageId) {
        if (fromComposer) input.value = content;
        toast("当前没有可引导的执行任务");
        return false;
      }
      state.chatSubmitPending = true;
      $("sendBtn").disabled = true;
      const messageContent = buildMessageContent(content);
      const userBubble = addBubble("user", content || `已添加 ${attachments.length} 个素材`);
      renderBubbleAttachments(userBubble, attachments);
      const bot = addBubble("bot", queueMode === "steer"
        ? "正在按补充要求调整当前任务..."
        : (activeQueueMessage() ? "已加入队列，等待前面的任务完成..." : "正在理解需求..."));
      bot._placeholder = true;
      try {
        const data = await api("/api/mastra-chat/messages", {
          method: "POST",
          blocking: false,
          json: {
            content: messageContent,
            installation_id: currentInstallationId(),
            session_id: state.activeChatSessionId,
            attachments,
            queue_mode: queueMode,
            target_message_id: targetMessageId,
          },
        });
        const msg = data.message || {};
        if (msg.id) {
          state.historyItems.push({ message: msg, events: [] });
          state.historyItems = state.historyItems.slice(-40);
          renderOfficeEmployees();
          renderWorkList();
        }
        if (msg.id) startSse(msg.id, bot);
        clearUploads();
        await loadChatQueue();
        loadChatSessions().catch(() => {});
        await Promise.all([refreshDeviceStatus(), refreshMastraStatus()]);
        return true;
      } catch (err) {
        bot.classList.add("err");
        setBubbleText(bot, err.message || "发送失败");
        if (fromComposer && !String(input.value || "").trim()) {
          input.value = content;
          autosizeMessageInput();
        }
        return false;
      } finally {
        state.chatSubmitPending = false;
        $("sendBtn").disabled = false;
        ensureConversationComposerReady({ scroll: false });
        if (options.source !== "voice") focusMessageInput();
      }
    }

    $("sendForm").addEventListener("submit", async (evt) => {
      evt.preventDefault();
      await submitChatMessage();
    });

    $("chatQueueSummary")?.addEventListener("click", () => {
      state.chatQueueExpanded = !state.chatQueueExpanded;
      renderChatQueue();
    });

    $("chatQueueList")?.addEventListener("click", async (evt) => {
      const cancel = evt.target.closest("[data-chat-cancel]");
      if (cancel) {
        await cancelChatQueueMessage(cancel.dataset.chatCancel || "", cancel);
        return;
      }
      const remove = evt.target.closest("[data-chat-queue-delete]");
      if (remove) {
        await deleteChatQueueMessage(remove.dataset.chatQueueDelete || "", remove);
        return;
      }
      const edit = evt.target.closest("[data-chat-queue-edit]");
      if (edit) {
        const row = edit.closest("[data-chat-queue-row]");
        row?.querySelector(".chat-queue-copy")?.classList.add("hidden");
        row?.querySelector(".chat-queue-actions")?.classList.add("hidden");
        row?.querySelector(".chat-queue-edit")?.classList.remove("hidden");
        row?.querySelector("[data-chat-queue-edit-input]")?.focus();
        return;
      }
      const editCancel = evt.target.closest("[data-chat-queue-edit-cancel]");
      if (editCancel) {
        const row = editCancel.closest("[data-chat-queue-row]");
        row?.querySelector(".chat-queue-copy")?.classList.remove("hidden");
        row?.querySelector(".chat-queue-actions")?.classList.remove("hidden");
        row?.querySelector(".chat-queue-edit")?.classList.add("hidden");
        return;
      }
      const save = evt.target.closest("[data-chat-queue-save]");
      if (save) {
        const row = save.closest("[data-chat-queue-row]");
        await saveChatQueueMessage(save.dataset.chatQueueSave || "", row, save);
      }
    });

    $("composerSteerBtn")?.addEventListener("click", async () => {
      const targetMessageId = String($("composerSteerBtn").dataset.targetMessageId || "");
      await submitChatMessage(null, { queueMode: "steer", targetMessageId });
    });

    (async function init() {
      loadH5Branding().catch(() => {});
      setAuthTab("sms");
      setTaskAbility("comfly.seedance.tvc.pipeline");
      const ok = await loadMe();
      if (!ok) {
        await showLoginShell();
      }
      markH5PageReady("boot_ready");
      setInterval(() => {
        if (!state.token || document.visibilityState === "hidden") return;
        if (["assetLibrary", "mountedAccounts"].includes(activeViewKey())) return;
        refreshDeviceStatus();
      }, 7000);
      setInterval(() => {
        if (!state.token) return;
        if (document.visibilityState === "hidden") return;
        if (!["office", "workflow", "workList", "runList", "runDetail", "department", "secretary"].includes(activeViewKey())) return;
        const activeStatuses = new Set(["pending", "claimed", "processing", "running"]);
        if (!(state.runs || []).some((row) => activeStatuses.has(String(row && row.status || "").toLowerCase()))) return;
        loadRuns({
          reset: false,
          limit: 20,
          compact: true,
          preserveExisting: true,
          silent: true,
        });
      }, 15000);
    })();
